package gofile

import (
	"os"
	"path/filepath"
	"testing"
)

func TestGenerated(t *testing.T) {
	dir := t.TempDir()
	cases := map[string]struct {
		src  string
		want bool
	}{
		"gen.go":     {"// Code generated by stringer. DO NOT EDIT.\n\npackage p\n", true},
		"hand.go":    {"// Package p does things.\npackage p\n", false},
		"late.go":    {"package p\n\n// Code generated by stringer. DO NOT EDIT.\n", false},
		"partial.go": {"// Code generated by hand, edit freely.\npackage p\n", false},
	}
	for name, c := range cases {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte(c.src), 0o644); err != nil {
			t.Fatal(err)
		}
		if got := Generated(path); got != c.want {
			t.Errorf("Generated(%s) = %v, want %v", name, got, c.want)
		}
	}
	if Generated(filepath.Join(dir, "missing.go")) {
		t.Error("missing file reported as generated")
	}
}
